      "path": "src/tools/rec.ts",
      "content": "/**\n * term_rec — 开始/停止录制(按会话或按命令),支持 marker 标记与状态查询。\n *\n * 语义对齐官方 asciinema rec:本工具负责「开始录制 → 缓冲输出 → 停止并写盘」。\n * 录制来源为当前 Agent 会话的 tool/result 事件流;输入事件默认不录(隐私默认)。\n *\n * @module dsh-asciinema/tools/rec\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { ToolDefinition, ToolRunContext } from '@deepseek-ai/dsh-tools'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { JsonValue } from '@deepseek-ai/dsh-session'\nimport type {} from '@deepseek-ai/dsh-fs'\nimport type { AsciinemaConfig } from '../index.ts'\nimport { RecorderRegistry, type RecordingScope } from '../recorder.ts'\nimport { saveCastFile, sanitizeName } from '../cast-io.ts'\nimport { castDuration } from '../cast-core.ts'\n\nexport type TermRecAction = 'start' | 'stop' | 'mark' | 'status'\n\nexport interface TermRecArgs {\n  action?: TermRecAction\n  name?: string\n  scope?: RecordingScope\n  record_input?: boolean\n  marker?: string\n}\n\nexport interface TermRecResult {\n  status: string\n  message: string\n  name?: string\n  scope?: string\n  path?: string\n  absPath?: string\n  events?: number\n  truncated?: boolean\n  duration?: number\n}\n\nexport interface RecToolDeps {\n  ctx: Context\n  registry: RecorderRegistry\n  config: AsciinemaConfig\n}\n\n/** 未命名时的时间戳基名。 */\nfunction timestampName(prefix: string): string {\n  return `${prefix}-${Date.now().toString(36)}`\n}\n\nfunction defaultName(scope: RecordingScope, requested: string | undefined): { name: string; autoNamed: boolean } {\n  if (requested !== undefined && requested !== '') return { name: sanitizeName(requested), autoNamed: false }\n  return { name: timestampName(scope === 'command' ? 'cmd' : 'session'), autoNamed: true }\n}\n\n/** 状态/提示的纯文本渲染(从返回值构建,遵守 output.render 纯函数约束)。 */\nfunction renderRec(value: TermRecResult): string {\n  const lines: string[] = []\n  switch (value.status) {\n    case 'recording':\n      lines.push(`🎬 录制中:${value.name ?? ''} (${value.scope ?? 'session'}) — 工具输出将被缓冲为 v2 cast`)\n      lines.push('  停止:term_rec action=stop  name=<同款名>')\n      break\n    case 'saved':\n      lines.push(`💾 已保存 ${value.path ?? ''}（${value.events ?? 0} 事件,${value.duration ?? 0}s）`)\n      if (value.truncated === true) lines.push('  ⚠️ 已达到容量上限,录制已封存(后续输出不再记录)')\n      lines.push('  回放:term_play path=<该路径>  /  文本:term_cat path=<该路径>')\n      break\n    case 'discarded':\n      lines.push(`🗑️ ${value.message}`)\n      break\n    case 'mark':\n      lines.push(`📍 ${value.message}`)\n      break\n    default:\n      lines.push(value.message)\n  }\n  return lines.join('\\n')\n}\n\nexport function createTermRecTool(deps: RecToolDeps): ToolDefinition {\n  return defineTool({\n    name: 'term_rec',\n    description:\n      '开始/停止把当前会话的工具输出录制为 asciinema v2 (.cast) 文件。' +\n      'action=start 开始(scope=session 录到显式 stop;scope=command 在当前步骤结束时自动封存),' +\n      '同名再调 action=stop 停止并写盘到工作区 .casts/ 目录;' +\n      'action=mark 在录制中插入标记;action=status 查询活动录制。' +\n      '隐私默认:只录输出,不录输入(record_input=true 才录)。',\n    parameters: {\n      action: {\n        type: 'string',\n        enum: ['start', 'stop', 'mark', 'status'],\n        description: '操作,默认 start',\n      },\n      name: {\n        type: 'string',\n        description: '录制名(写盘文件基名);缺省自动生成,自动命名的录制在会话结束后自动丢弃',\n      },\n      scope: {\n        type: 'string',\n        enum: ['session', 'command'],\n        description: '录制范围,默认 session',\n      },\n      record_input: {\n        type: 'boolean',\n        description: '是否记录用户输入事件,默认 false(隐私默认)',\n      },\n      marker: {\n        type: 'string',\n        description: 'action=mark 时的标记文案',\n      },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          status: { type: 'string', required: true },\n          message: { type: 'string', required: true },\n          name: { type: 'string' },\n          scope: { type: 'string' },\n          path: { type: 'string' },\n          absPath: { type: 'string' },\n          events: { type: 'number' },\n          truncated: { type: 'boolean' },\n          duration: { type: 'number' },\n        },\n      },\n      render: (_args, value) => [{ type: 'text', text: renderRec(value) }],\n      presentationMeta: (_args, value) => value as unknown as JsonValue,\n    },\n    async execute(args: TermRecArgs, exec: ToolRunContext) {\n      const action = args.action ?? 'start'\n      const session = exec.agent?.session\n\n      if (action === 'status') {\n        // 只列出当前会话的活动录制(跨会话隔离)。\n        const active = deps.registry.active(session)\n        const list = active.map((rec) => `「${rec.name}」(${rec.scope},${rec.eventCount} 事件)`)\n        return {\n          status: 'ok',\n          message: list.length > 0 ? `录制中:${list.join(', ')}` : '当前没有活动录制',\n          events: active.reduce((sum, rec) => sum + rec.eventCount, 0),\n        }\n      }\n\n      if (session === undefined) {\n        return {\n          status: 'error',\n          message: 'term_rec 只能在会话内调用(缺少 agent 会话上下文)',\n        }\n      }\n\n      if (action === 'start') {\n        const scope = args.scope ?? 'session'\n        const { name, autoNamed } = defaultName(scope, args.name)\n        if (deps.registry.get(name, session) !== undefined) {\n          return { status: 'error', message: `本会话已有同名录制「${name}」,请先 term_rec action=stop` }\n        }\n        const recorder = deps.registry.start(deps.ctx, session, {\n          name,\n          scope,\n          autoNamed,\n          recordInput: args.record_input ?? deps.config.recordInput,\n          writerOptions: {\n            width: deps.config.width,\n            height: deps.config.height,\n            maxEvents: deps.config.maxEvents,\n            maxBytes: deps.config.maxBytes,\n          },\n        })\n        return {\n          status: 'recording',\n          name,\n          scope,\n          message: `开始录制「${name}」(${scope})`,\n        }\n      }\n\n      if (action === 'mark') {\n        const rec = args.name !== undefined\n          ? deps.registry.get(sanitizeName(args.name), session)\n          : deps.registry.soloActiveOf(session)\n        if (rec === undefined) {\n          return { status: 'error', message: '本会话没有活动录制可标记(先 term_rec action=start)' }\n        }\n        const ok = rec.mark(args.marker ?? 'mark')\n        if (!ok) return { status: 'error', message: `录制「${rec.name}」已停止,无法插入标记` }\n        return { status: 'mark', name: rec.name, events: rec.eventCount, message: `已在「${rec.name}」插入标记` }\n      }\n\n      // action === 'stop':只按当前会话找到并停止录制(跨会话隔离)。\n      const requested = args.name !== undefined ? sanitizeName(args.name) : undefined\n      const recorder = requested !== undefined ? deps.registry.take(requested, session) : (() => {\n        const solo = deps.registry.soloActiveOf(session)\n        return solo !== undefined ? deps.registry.take(solo.name, session) : undefined\n      })()\n      if (recorder === undefined) {\n        return { status: 'error', message: '本会话没有可停止的录制(先 term_rec action=start 或指定存在 name)' }\n      }\n\n      const cast = recorder.finalCast ?? recorder.stop()\n      if (cast === undefined) {\n        return { status: 'error', message: `录制「${recorder.name}」没有可保存的内容` }\n      }\n\n      // 未命名且无内容 → 丢弃\n      if (recorder.autoNamed && cast.events.length === 0) {\n        return {\n          status: 'discarded',\n          name: recorder.name,\n          message: '未命名录制没有任何输出,已自动丢弃(命名录制后即可保存)',\n        }\n      }\n\n      const saved = await saveCastFile(\n        deps.ctx,\n        session,\n        deps.config.castsDir,\n        recorder.name,\n        cast,\n        exec.signal,\n      )\n      return {\n        status: 'saved',\n        name: recorder.name,\n        scope: recorder.scope,\n        path: saved.relPath,\n        absPath: saved.absPath,\n        events: cast.events.length,\n        truncated: recorder.isTruncated,\n        duration: castDuration(cast),\n        message: `已保存录制「${recorder.name}」`,\n      }\n    },\n  })\n}"
    },
    {
      "path": "src/tools/play.ts",
      "content": "/**\n * term_play — 回放 .cast:生成内嵌 asciinema-player 的离线 HTML(默认),\n * 会话内返回可点击文件;text 模式输出 cat 文本(无浏览器时兜底)。\n *\n * @module dsh-asciinema/tools/play\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { ToolDefinition, ToolRunContext } from '@deepseek-ai/dsh-tools'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { JsonValue } from '@deepseek-ai/dsh-session'\nimport type {} from '@deepseek-ai/dsh-fs'\nimport type { AsciinemaConfig } from '../index.ts'\nimport {\n  readCastText,\n  resolveTarget,\n  loadPlayerTemplate,\n  renderPlayerHtml,\n  htmlPathForCast,\n} from '../cast-io.ts'\nimport { castToText, castDuration, parseCast, validateCast } from '../cast-core.ts'\n\nexport type TermPlayMode = 'auto' | 'html' | 'text'\n\nexport interface TermPlayArgs {\n  path: string\n  mode?: TermPlayMode\n}\n\nexport interface TermPlayResult {\n  mode: 'html' | 'text'\n  path: string\n  htmlPath?: string\n  events: number\n  duration: number\n  width: number\n  height: number\n  title?: string\n  text?: string\n  issues: string[]\n}\n\n/** 缺省导出模板(assets/player.html 缺失时的兜底,保证 html 模式仍可用)。 */\nconst FALLBACK_TEMPLATE = `<!doctype html>\n<html lang=\"zh-CN\">\n<head><meta charset=\"utf-8\"><title>__TITLE__ — asciinema 回放</title>\n<style>body{font-family:ui-monospace,Menlo,Consolas,monospace;background:#111;color:#eee;padding:2rem}\n#stage{white-space:pre-wrap;line-height:1.2;max-width:80ch}#bar{display:flex;gap:1rem;align-items:center;margin-bottom:1rem;color:#aaa}\nbutton{background:#222;color:#eee;border:1px solid #444;border-radius:4px;padding:.3rem .8rem;cursor:pointer}\n</style></head>\n<body>\n<h2>__TITLE__</h2>\n<div id=\"bar\">\n<button id=\"btn-play\">▶ 播放</button>\n<button id=\"btn-reset\">⟲ 复位</button>\n<span id=\"cur\">0.000s</span>/<span id=\"tot\">0s</span>\n<select id=\"speed\"><option value=\"1\">1x</option><option value=\"2\">2x</option><option value=\"4\">4x</option><option value=\"0.5\">0.5x</option></select>\n</div>\n<pre id=\"stage\"></pre>\n<script type=\"application/json\" id=\"cast-data\">__CAST_JSON__</script>\n<script>\nconst cast = JSON.parse(document.getElementById('cast-data').textContent);\nconst stage = document.getElementById('stage');\nlet lines = [], idx = 0, timer = null, playing = false;\nconst SCREEN = /[\\\\u001B\\\\u009B][[\\\\]()#;?]*(?:(?:(?:[a-zA-Z\\\\d]*(?:;[-a-zA-Z\\\\d/#&.:=?%@~_]+)*)?\\\\u0007)|(?:(?:\\\\d{1,4}(?:[;:]\\\\d{0,4})*)?[\\\\dA-PR-TZcf-nq-uy=><~]))/g;\nfunction append(chunk) { lines.push(...chunk.replace(SCREEN, '').split(/\\\\n/)); if (lines.length > cast.height) lines = lines.slice(-cast.height); }\nfunction render() { stage.textContent = lines.join('\\\\n').slice(-200000); }\nfunction reset() { stop(); lines = []; idx = 0; cur(0); for (const e of cast.events) if (e[1] === 'o') append(e[2]); render(); cur(cast.events[0] && cast.events[0][0] || 0); }\nfunction cur(t) { document.getElementById('cur').textContent = t.toFixed(3) + 's'; }\nfunction stop() { if (timer) clearTimeout(timer); timer = null; playing = false; document.getElementById('btn-play').textContent = '▶ 播放'; }\nfunction step() {\n  if (idx >= cast.events.length) { stop(); reset(); return; }\n  const e = cast.events[idx++];\n  if (e[1] === 'o') append(e[2]);\n  const d = Math.max(e[0], 0.001) / Number(document.getElementById('speed').value);\n  cur(cast.events.slice(0, idx).reduce((s, x) => s + x[0], 0));\n  timer = setTimeout(step, d * 1000);\n}\ndocument.getElementById('btn-play').onclick = () => { if (playing) { stop(); return; } playing = true; document.getElementById('btn-play').textContent = '⏸ 暂停'; step(); };\ndocument.getElementById('btn-reset').onclick = reset;\nconst total = cast.events.reduce((s, x) => s + x[0], 0);\ndocument.getElementById('tot').textContent = total.toFixed(1) + 's';\nreset();\n</script>\n</body></html>`\n\nexport interface PlayToolDeps {\n  ctx: Context\n  config: AsciinemaConfig\n}\n\nexport function createTermPlayTool(deps: PlayToolDeps): ToolDefinition {\n  return defineTool({\n    name: 'term_play',\n    description:\n      '回放一个 asciinema v2 (.cast) 文件。默认 mode=html:把播放器模板与 cast 数据内嵌成自包含 HTML(离线可播),' +\n      '写到 .cast 同目录并返回可点击链接;mode=text 输出去除控制序列的纯文本(无浏览器环境时用这个)。' +\n      '路径相对会话工作区,如 .casts/demo.cast。',\n    parameters: {\n      path: { type: 'string', required: true, description: '.cast 文件路径(相对会话工作区)' },\n      mode: {\n        type: 'string',\n        enum: ['auto', 'html', 'text'],\n        description: '回放模式,默认 auto(html;text 为兜底)',\n      },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          mode: { type: 'string', required: true },\n          path: { type: 'string', required: true },\n          htmlPath: { type: 'string' },\n          events: { type: 'number', required: true },\n          duration: { type: 'number', required: true },\n          width: { type: 'number', required: true },\n          height: { type: 'number', required: true },\n          title: { type: 'string' },\n          text: { type: 'string' },\n          issues: { type: 'array', items: { type: 'string' }, required: true },\n        },\n      },\n      render: (args, value) => {\n        const lines: string[] = []\n        if (value.mode === 'html') {\n          lines.push(`▶ 回放已生成:${value.htmlPath ?? ''}（${value.events} 事件,约 ${value.duration}s,${value.width}×${value.height}）`)\n          lines.push(`  点击打开:${value.htmlPath ?? ''}(离线 HTML,可直接浏览器打开)`)\n          if (value.title !== undefined) lines.push(`  标题:${value.title}`)\n          lines.push(`  文本化:term_cat path=${args.path}  /  text 模式:term_play path=${args.path} mode=text`)\n        } else {\n          lines.push(`▶ 文本化回放(${value.events} 事件,约 ${value.duration}s):`)\n          lines.push('```console')\n          lines.push(value.text ?? '')\n          lines.push('```')\n        }\n        if (value.issues.length > 0) {\n          lines.push(`⚠ 解析告警:${value.issues.join('; ')}`)\n        }\n        return [{ type: 'text', text: lines.join('\\n') }]\n      },\n      presentationMeta: (_args, value) => ({\n        type: 'asciinema-playback',\n        path: value.path,\n        htmlPath: value.htmlPath,\n        events: value.events,\n        duration: value.duration,\n      }) as JsonValue,\n    },\n    async execute(args: TermPlayArgs, exec: ToolRunContext) {\n      const session = exec.agent?.session\n      const raw = await readCastText(deps.ctx, session, args.path, exec.signal)\n      const parsed = parseCast(raw)\n      if (parsed.cast === null) {\n        const first = parsed.issues[0]\n        throw new Error(`无法解析 .cast 文件:${first !== undefined ? first.message : 'unknown error'}(path=${args.path})`)\n      }\n      const cast = parsed.cast\n      const seen = new Set(parsed.issues.map((issue) => issue.message))\n      const warnings = validateCast(cast).filter((issue) => {\n        if (seen.has(issue.message)) return false\n        seen.add(issue.message)\n        return true\n      })\n      const issues = [...seen]\n\n      const mode = args.mode ?? 'auto'\n      if (mode === 'text') {\n        return {\n          mode: 'text',\n          path: args.path,\n          events: cast.events.length,\n          duration: castDuration(cast),\n          width: cast.width,\n          height: cast.height,\n          title: cast.title,\n          text: castToText(cast),\n          issues,\n        }\n      }\n\n      // html(默认)/auto:生成自包含回放页\n      const template = (await loadPlayerTemplate(deps.ctx, exec.signal)) ?? FALLBACK_TEMPLATE\n      const html = renderPlayerHtml(template, cast, cast.title ?? args.path)\n      const htmlPath = htmlPathForCast(args.path)\n      const target = await resolveTarget(deps.ctx, session, htmlPath, exec.signal)\n      await deps.ctx.fs.writeText(target, html, undefined, exec.signal)\n      return {\n        mode: 'html',\n        path: args.path,\n        htmlPath,\n        events: cast.events.length,\n        duration: castDuration(cast),\n        width: cast.width,\n        height: cast.height,\n        title: cast.title,\n        issues,\n      }\n    },\n  })\n}"
    },
    {
      "path": "src/tools/cat.ts",
      "content": "/**\n * term_cat — .cast → 纯文本(对齐 asciinema cat 语义:输出事件拼接、去控制序列)。\n *\n * @module dsh-asciinema/tools/cat\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { ToolDefinition, ToolRunContext } from '@deepseek-ai/dsh-tools'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type {} from '@deepseek-ai/dsh-fs'\nimport { readCastText } from '../cast-io.ts'\nimport { castToText, parseCast } from '../cast-core.ts'\n\nexport interface TermCatArgs {\n  path: string\n  raw?: boolean\n  include_input?: boolean\n}\n\nexport interface CatToolDeps {\n  ctx: Context\n}\n\nexport function createTermCatTool(deps: CatToolDeps): ToolDefinition {\n  return defineTool({\n    name: 'term_cat',\n    description:\n      '把一个 asciinema v2 (.cast) 文件转为纯文本(asciinema cat 语义):顺序拼接输出事件,' +\n      '默认剥离 ANSI 控制序列;raw=true 保留控制序列原文(终端协议保真)。' +\n      '路径相对会话工作区,如 .casts/demo.cast。',\n    parameters: {\n      path: { type: 'string', required: true, description: '.cast 文件路径(相对会话工作区)' },\n      raw: { type: 'boolean', description: '保留 ANSI 控制序列,默认 false(剥离)' },\n      include_input: { type: 'boolean', description: '是否把输入(i)事件也拼入文本,默认 false' },\n    },\n    output: {\n      schema: { type: 'string' },\n      render: (args, value) => {\n        const header = `▶ ${args.path}(${value.length} 字符)`\n        return [{ type: 'text', text: `${header}\\n${value}` }]\n      },\n      presentationMeta: (_args, value) => ({ type: 'asciinema-cat', chars: value.length }),\n    },\n    async execute(args: TermCatArgs, exec: ToolRunContext) {\n      const session = exec.agent?.session\n      const raw = await readCastText(deps.ctx, session, args.path, exec.signal)\n      const parsed = parseCast(raw)\n      if (parsed.cast === null) {\n        const first = parsed.issues[0]\n        throw new Error(`无法解析 .cast 文件:${first !== undefined ? first.message : 'unknown error'}(path=${args.path})`)\n      }\n      return castToText(parsed.cast, {\n        stripAnsi: !(args.raw ?? false),\n        includeInput: args.include_input ?? false,\n      })\n    },\n  })\n}"
    },
    {
      "path": "assets/player.html",
      "content": "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>__TITLE__ — asciinema 回放 (dsh-asciinema)</title>\n<style>\n  :root { color-scheme: dark; }\n  * { box-sizing: border-box; }\n  body {\n    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, \"Liberation Mono\", monospace;\n    background: #0d1117; color: #e6edf3; margin: 0; padding: 2rem 1.5rem;\n  }\n  header { max-width: 92ch; margin: 0 auto 1rem; }\n  h1 { font-size: 1.1rem; margin: 0 0 .25rem; color: #f0f6fc; }\n  .meta { font-size: .8rem; color: #8b949e; }\n  .player {\n    max-width: 92ch; margin: 0 auto; background: #010409; border: 1px solid #30363d;\n    border-radius: 8px; overflow: hidden;\n  }\n  .bar {\n    display: flex; flex-wrap: wrap; gap: .6rem 1rem; align-items: center;\n    padding: .55rem .9rem; background: #161b22; border-bottom: 1px solid #30363d;\n    font-size: .82rem;\n  }\n  button {\n    background: #21262d; color: #e6edf3; border: 1px solid #30363d;\n    border-radius: 6px; padding: .3rem .8rem; cursor: pointer; font: inherit;\n  }\n  button:hover { background: #30363d; }\n  select { background: #21262d; color: #e6edf3; border: 1px solid #30363d; border-radius: 6px; font: inherit; }\n  input[type=range] { flex: 1 1 8rem; min-width: 8rem; accent-color: #2f81f7; }\n  .time { color: #8b949e; white-space: nowrap; }\n  .status { color: #7ee787; }\n  .markers { display: flex; flex-wrap: wrap; gap: .4rem; padding: .4rem .9rem; background: #161b22; border-bottom: 1px solid #30363d; }\n  .marker { font-size: .75rem; color: #f0b429; background: #271d04; border: 1px solid #8a6702; border-radius: 999px; padding: .1rem .5rem; }\n  #stage-wrap { padding: .9rem; overflow: auto; }\n  #stage {\n    white-space: pre-wrap; word-break: break-all; line-height: 1.25;\n    min-height: 1.6em; margin: 0; font-family: inherit; letter-spacing: 0;\n  }\n  .idle-note { color: #8b949e; font-style: italic; }\n  footer { max-width: 92ch; margin: .8rem auto 0; font-size: .72rem; color: #6e7681; }\n</style>\n</head>\n<body>\n<header>\n  <h1>__TITLE__</h1>\n  <div class=\"meta\" id=\"meta\">…</div>\n</header>\n<div class=\"player\">\n  <div class=\"bar\">\n    <button id=\"btn-play\" title=\"空格切换\">▶ 播放</button>\n    <button id=\"btn-reset\">⟲ 复位</button>\n    <label>速度\n      <select id=\"speed\">\n        <option value=\"0.25\">0.25x</option>\n        <option value=\"0.5\">0.5x</option>\n        <option value=\"1\" selected>1x</option>\n        <option value=\"2\">2x</option>\n        <option value=\"4\">4x</option>\n      </select>\n    </label>\n    <span class=\"time\" id=\"time\">0.000s / 0.0s</span>\n    <span class=\"status\" id=\"status\"></span>\n    <input type=\"range\" id=\"seek\" min=\"0\" max=\"1000\" value=\"0\" title=\"拖动定位\">\n  </div>\n  <div class=\"markers\" id=\"markers\"></div>\n  <div id=\"stage-wrap\">\n    <pre id=\"stage\"></pre>\n  </div>\n</div>\n<footer>\n  dsh-asciinema 离线播放器 — 数据已内嵌(<span id=\"mode-label\">inline</span>);\n  也可用 ?url=xxx.cast 直接加载外部 .cast 文件。\n</footer>\n\n<script type=\"application/json\" id=\"cast-data\">__CAST_JSON__</script>\n<script>\n(function () {\n  'use strict'\n  // ---------- ANSI 控制序列剥离(CSI / OSC / 单字符转义) ----------\n  var ANSI = /[\\u001B\\u009B][[\\]()#;?]*(?:(?:(?:[a-zA-Z\\d]*(?:;[-a-zA-Z\\d/#&.:=?%@~_]+)*)?\\u0007)|(?:(?:\\d{1,4}(?:[;:]\\d{0,4})*)?[\\dA-PR-TZcf-nq-uy=><~]))/g\n  function stripAnsi(text) { return text.replace(ANSI, '') }\n\n  var stage = document.getElementById('stage')\n  var timeEl = document.getElementById('time')\n  var statusEl = document.getElementById('status')\n  var seekEl = document.getElementById('seek')\n  var markersEl = document.getElementById('markers')\n  var btnPlay = document.getElementById('btn-play')\n  var btnReset = document.getElementById('btn-reset')\n  var speedEl = document.getElementById('speed')\n\n  var cast = null\n  var lines = []\n  var width = 100\n  var height = 40\n  var markers = []\n  var idx = 0\n  var timer = null\n  var playing = false\n\n  function loadCast() {\n    var raw = document.getElementById('cast-data').textContent.trim()\n    if (raw && raw !== '__CAST_JSON__' && raw !== 'null') {\n      try { cast = JSON.parse(raw) } catch (e) { cast = null }\n      document.getElementById('mode-label').textContent = 'inline'\n    }\n    if (!cast) {\n      var url = new URLSearchParams(location.search).get('url') || '__CAST_URL__'\n      if (url && url !== '') {\n        return fetch(url).then(function (r) { return r.json() }).then(function (data) {\n          cast = data\n          document.getElementById('mode-label').textContent = 'url'\n          return true\n        }).catch(function () { return false })\n      }\n    }\n    return Promise.resolve(cast !== null)\n  }\n\n  function parseCast(c) {\n    width = (c.width >= 1 && c.width <= 1000) ? Math.floor(c.width) : 100\n    height = (c.height >= 1 && c.height <= 1000) ? Math.floor(c.height) : 40\n    var list = Array.isArray(c.events) ? c.events : []\n    markers = []\n    for (var i = 0; i < list.length; i++) {\n      var e = list[i]\n      if (e && e[1] === 'm' && typeof e[2] === 'string' && e[2]) markers.push(e[2])\n    }\n    return { idle: (typeof c.idle_time_limit === 'number') ? c.idle_time_limit : null }\n  }\n\n  function clearStage() { lines = []; stage.textContent = ''; }\n\n  function appendOutput(chunk) {\n    var text = stripAnsi(String(chunk))\n    var parts = text.split('\\n')\n    for (var i = 0; i < parts.length; i++) {\n      if (i > 0) lines.push('')\n      lines[lines.length - 1] = (lines[lines.length - 1] !== undefined ? lines[lines.length - 1] : '') + parts[i].replace(/\\r/g, '')\n    }\n    if (lines.length > height * 4) lines = lines.slice(-height * 4)\n    stage.textContent = lines.slice(-height).join('\\n')\n  }\n\n  function renderMeta(c) {\n    var parts = [\n      'version ' + (c.version !== undefined ? c.version : 2),\n      width + '×' + height,\n      cast ? cast.events.length + ' 事件' : '0 事件',\n      '约 ' + totalTime(cast).toFixed(1) + 's'\n    ]\n    if (c.timestamp) parts.push(new Date(c.timestamp * 1000).toISOString())\n    document.getElementById('meta').textContent = parts.join(' · ')\n  }\n\n  function totalTime(c) {\n    if (!c || !Array.isArray(c.events)) return 0\n    var t = 0\n    for (var i = 0; i < c.events.length; i++) t += (typeof c.events[i][0] === 'number' ? c.events[i][0] : 0)\n    return t\n  }\n\n  function elapsedAt(frameIdx) {\n    var t = 0\n    for (var i = 0; i < frameIdx && i < cast.events.length; i++) t += (typeof cast.events[i][0] === 'number' ? cast.events[i][0] : 0)\n    return t\n  }\n\n  function renderMarkers() {\n    markersEl.textContent = ''\n    if (markers.length === 0) { markersEl.style.display = 'none'; return }\n    markersEl.style.display = 'flex'\n    for (var i = 0; i < markers.length; i++) {\n      var chip = document.createElement('span')\n      chip.className = 'marker'\n      chip.textContent = '📍 ' + markers[i]\n      markersEl.appendChild(chip)\n    }\n  }\n\n  function updateTime() {\n    timeEl.textContent = elapsedAt(idx).toFixed(3) + 's / ' + totalTime(cast).toFixed(1) + 's'\n    var max = 1000\n    seekEl.value = String(Math.round((elapsedAt(idx) / Math.max(totalTime(cast), 0.001)) * max))\n  }\n\n  function stop() {\n    if (timer) clearTimeout(timer)\n    timer = null\n    playing = false\n    btnPlay.textContent = '▶ 播放'\n    statusEl.textContent = ''\n  }\n\n  function step() {\n    if (!cast) return\n    if (idx >= cast.events.length) {\n      stop()\n      return\n    }\n    var e = cast.events[idx]\n    var delay = typeof e[0] === 'number' && e[0] >= 0 ? e[0] : 0\n    idx += 1\n    if (e[1] === 'o') appendOutput(e[2])\n    updateTime()\n    var waitMs = delay * 1000 / Number(speedEl.value)\n    if (idleLimit !== null && delay > idleLimit) {\n      // 空闲超过 idle_time_limit:快进到下一帧前暂停提示\n      statusEl.textContent = '⏳ 空闲 ' + delay.toFixed(1) + 's(快进)'\n      waitMs = idleLimit * 1000 / Number(speedEl.value)\n    } else {\n      statusEl.textContent = ''\n    }\n    timer = setTimeout(step, waitMs)\n  }\n\n  var idleLimit = null\n\n  function resetTo(frameIdx, autoplay) {\n    stop()\n    clearStage()\n    idx = 0\n    for (var i = 0; i < frameIdx && i < cast.events.length; i++) {\n      var e = cast.events[i]\n      if (e[1] === 'o') appendOutput(e[2])\n    }\n    updateTime()\n    if (autoplay) { playing = true; btnPlay.textContent = '⏸ 暂停'; step() }\n  }\n\n  function togglePlay() {\n    if (!cast) return\n    if (playing) { stop(); return }\n    if (idx >= cast.events.length) resetTo(0, false)\n    playing = true\n    btnPlay.textContent = '⏸ 暂停'\n    step()\n  }\n\n  btnPlay.addEventListener('click', togglePlay)\n  btnReset.addEventListener('click', function () { resetTo(0, false) })\n  speedEl.addEventListener('change', function () {\n    if (playing) { stop(); togglePlay() }\n  })\n  seekEl.addEventListener('input', function () {\n    if (!cast) return\n    var target = (Number(seekEl.value) / 1000) * totalTime(cast)\n    var frame = 0\n    var acc = 0\n    for (var i = 0; i < cast.events.length; i++) {\n      if (acc >= target) break\n      acc += (typeof cast.events[i][0] === 'number' ? cast.events[i][0] : 0)\n      frame = i\n    }\n    resetTo(frame, false)\n  })\n  document.addEventListener('keydown', function (ev) {\n    if (ev.code === 'Space') { ev.preventDefault(); togglePlay() }\n  })\n\n  loadCast().then(function (ok) {\n    if (!ok) {\n      stage.textContent = '无法加载录制数据:缺少内嵌 cast 且 url 为空/不可达。'\n      statusEl.textContent = '加载失败'\n      return\n    }\n    idleLimit = parseCast(cast).idle\n    renderMeta(cast)\n    renderMarkers()\n    updateTime()\n  })\n})()\n</script>\n</body>\n</html>"
